// Nilad shared Error Workflow — build the owner Telegram alert (Arabic, PII-scrubbed, HTML-safe).
// Env: TELEGRAM_BOT_TOKEN / TELEGRAM_CHAT_ID are consumed by the downstream HTTP Request node.
// Input: Error Trigger item { json: { execution: { id, url, error?, lastNodeExecuted? },
//   workflow: { id, name }, node?: { name }, error?: { message, description?, stack? } } }
// Outputs ONLY: { tgText } — first line of the error, capped at 300 chars; no stack trace, no raw error, no PII.
const j = ($input.first() || {}).json || {};
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const exec = j.execution || {};
const wfName = (j.workflow && j.workflow.name) || 'unknown';
const nodeName = (j.node && j.node.name) || exec.lastNodeExecuted || 'unknown';
const execId = exec.id === undefined || exec.id === null || exec.id === '' ? 'unknown' : String(exec.id);

const errorSources = [j.error, exec.error, j.trigger && j.trigger.error].filter((e) => e && typeof e === 'object');
const pickText = (key) => {
  for (let i = 0; i < errorSources.length; i++) {
    const v = errorSources[i][key];
    if (typeof v === 'string' && v.trim()) return v;
  }
  return '';
};
const firstLine = (pickText('message') || pickText('description') || 'unknown error').split(/\r?\n/)[0].slice(0, 300);

const text = [
  '⚠️ n8n: تنبيه فشل',
  'الواجهة/Workflow: ' + wfName,
  'العقدة/node: ' + nodeName,
  'التنفيذ/execution: ' + execId,
  'السبب: ' + firstLine,
]
  .join('\n')
  .replace(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g, '[email]')
  .replace(/[0-9]{10,}/g, '[phone]');

return [{ json: {
    // n8n 2.41 blocks $env in node expressions (Code nodes may read it), so
    // the Telegram HTTP node gets its credentials from this item instead.
    tgToken: $env.TELEGRAM_BOT_TOKEN || '',
    tgChatId: $env.TELEGRAM_CHAT_ID || '', tgText: esc(text) } }];
